// Draws one keymap layer as SVG from keymap-drawer's parsed data
// (keymap.json, generated by zmk-corne-dongle/keymap-drawer/draw.sh).

export type Legend = string | { t?: string; s?: string; h?: string; type?: string };
export type PhysicalKey = { x: number; y: number; w: number; h: number; r: number; rx: number; ry: number };
export type Combo = { p: number[]; k: Legend; l?: string[] };
export type Keymap = { keys: PhysicalKey[]; layers: Record<string, Legend[]>; combos?: Combo[] };

export type Theme = { bg: string; key: string; keyDim: string; held: string; border: string; text: string; sub: string; combo: string };

export const THEMES: Record<"light" | "dark", Theme> = {
  light: { bg: "#ffffff", key: "#f2f3f5", keyDim: "#fafafa", held: "#ffe7b3", border: "#c4c7cf", text: "#1c1e22", sub: "#6b7080", combo: "#d9480f" },
  dark: { bg: "#1e1f23", key: "#2e3036", keyDim: "#24252a", held: "#5c4416", border: "#4a4d56", text: "#eceef2", sub: "#9aa0ad", combo: "#ff922b" },
};

const SCALE = 0.6; // physical units are 1/100 key; 1 key = 60px
const PAD = 8;

// keymap-drawer's $$mdi:...$$ icons that appear in this keymap
const ICONS: Record<string, string> = {
  "minus-circle-outline": "",
  transfer: "▽",
  "arrow-up-bold": "↑",
  "arrow-down-bold": "↓",
  "arrow-left-bold": "←",
  "arrow-right-bold": "→",
  "keyboard-return": "⏎",
  "keyboard-tab": "⇥",
  "keyboard-space": "␣",
  "keyboard-esc": "esc",
  backspace: "⌫",
  "apple-keyboard-command": "⌘",
  "apple-keyboard-option": "⌥",
  "apple-keyboard-shift": "⇧",
  "apple-keyboard-control": "⌃",
  "menu-up": "▲",
  "menu-down": "▼",
  "menu-left": "◀",
  "menu-right": "▶",
  "pan-up": "⇞",
  "pan-down": "⇟",
  "mouse-left-click-outline": "LMB",
  "mouse-right-click-outline": "RMB",
  "mouse-scroll-wheel": "MMB",
  "keyboard-tab-reverse": "⇤",
  "volume-off": "mute",
  "progress-download": "boot",
  "backup-restore": "reset",
  "star-four-points": "hyper",
  mouse: "",
};

function text(legend: string | undefined): string {
  if (!legend) return "";
  return legend.replace(/\$\$mdi:([\w-]+)\$\$/g, (_, name: string) => ICONS[name] ?? name);
}

function esc(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function normalize(legend: Legend): { t?: string; s?: string; h?: string; type?: string } {
  return typeof legend === "string" ? { t: legend } : legend;
}

// rotate a point (physical units) around the key's rotation origin
function rotated(k: PhysicalKey, x: number, y: number): [number, number] {
  if (!k.r) return [x, y];
  const a = (k.r * Math.PI) / 180;
  const dx = x - k.rx;
  const dy = y - k.ry;
  return [k.rx + dx * Math.cos(a) - dy * Math.sin(a), k.ry + dx * Math.sin(a) + dy * Math.cos(a)];
}

function center(k: PhysicalKey): [number, number] {
  const [cx, cy] = rotated(k, k.x + k.w / 2, k.y + k.h / 2);
  return [cx * SCALE + PAD, cy * SCALE + PAD];
}

export function drawLayer(keymap: Keymap, layer: string, theme: Theme): string {
  const bindings = keymap.layers[layer];
  const corners = keymap.keys.flatMap((k) =>
    [
      [k.x, k.y],
      [k.x + k.w, k.y],
      [k.x, k.y + k.h],
      [k.x + k.w, k.y + k.h],
    ].map(([x, y]) => rotated(k, x, y)),
  );
  const maxX = Math.max(...corners.map((c) => c[0]));
  const maxY = Math.max(...corners.map((c) => c[1]));
  const width = maxX * SCALE + PAD * 2;
  const height = maxY * SCALE + PAD * 2;
  const out: string[] = [];

  out.push(
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" font-family="-apple-system, Helvetica, sans-serif">`,
    `<rect width="100%" height="100%" rx="10" fill="${theme.bg}"/>`,
  );

  // combos: dashed lines between the keys (under them), result in a pill at the midpoint
  const pills: string[] = [];
  for (const combo of combosFor(keymap, layer)) {
    const points = combo.p.map((p) => center(keymap.keys[p]));
    const mx = points.reduce((a, p) => a + p[0], 0) / points.length;
    const my = points.reduce((a, p) => a + p[1], 0) / points.length;
    for (const [px, py] of points) {
      out.push(`<line x1="${px}" y1="${py}" x2="${mx}" y2="${my}" stroke="${theme.combo}" stroke-width="2" stroke-dasharray="5 4"/>`);
    }
    const label = esc(text(normalize(combo.k).t));
    pills.push(`<rect x="${mx - 13}" y="${my - 11}" width="26" height="22" rx="11" fill="${theme.combo}"/>`);
    pills.push(`<text x="${mx}" y="${my}" font-size="14" font-weight="bold" fill="${theme.bg}" text-anchor="middle" dominant-baseline="central">${label}</text>`);
  }

  keymap.keys.forEach((k, i) => {
    const b = normalize(bindings[i] ?? "");
    const x = k.x * SCALE + PAD;
    const y = k.y * SCALE + PAD;
    const w = k.w * SCALE;
    const h = k.h * SCALE;
    const rotate = k.r ? ` transform="rotate(${k.r} ${k.rx * SCALE + PAD} ${k.ry * SCALE + PAD})"` : "";
    const fill = b.type === "held" ? theme.held : b.type === "none" || b.type === "trans" ? theme.keyDim : theme.key;
    const tap = esc(text(b.t));
    const size = tap.length <= 2 ? 20 : tap.length <= 4 ? 14 : 11;

    out.push(`<g${rotate}>`);
    out.push(`<rect x="${x + 2}" y="${y + 2}" width="${w - 4}" height="${h - 4}" rx="7" fill="${fill}" stroke="${theme.border}"/>`);
    out.push(
      `<text x="${x + w / 2}" y="${y + h / 2}" font-size="${size}" fill="${b.type === "trans" ? theme.sub : theme.text}" text-anchor="middle" dominant-baseline="central">${tap}</text>`,
    );
    if (b.s) {
      out.push(`<text x="${x + w / 2}" y="${y + 13}" font-size="11" fill="${theme.combo}" text-anchor="middle">${esc(text(b.s))}</text>`);
    }
    if (b.h) {
      out.push(`<text x="${x + w / 2}" y="${y + h - 8}" font-size="11" fill="${theme.sub}" text-anchor="middle">${esc(text(b.h))}</text>`);
    }
    out.push(`</g>`);
  });

  out.push(...pills);
  out.push(`</svg>`);
  return out.join("\n");
}

export function combosFor(keymap: Keymap, layer: string): Combo[] {
  return (keymap.combos ?? []).filter((c) => !c.l || c.l.includes(layer));
}

export function legendText(legend: Legend): string {
  return text(normalize(legend).t);
}
